    "explanation": "Mô hình khảm động mô tả chính xác hơn vì nó phù hợp với các bằng chứng thực nghiệm quan sát được về hành vi của protein màng: trong một thí nghiệm kinh điển, khi dung hợp hai tế bào (một tế bào người và một tế bào chuột) mang các protein màng được đánh dấu huỳnh quang khác màu, ban đầu protein của mỗi loại tế bào tập trung ở một nửa màng tế bào lai, nhưng chỉ sau một khoảng thời gian ngắn, hai loại protein đã phân bố xen kẽ, trộn lẫn đều khắp trên toàn bộ bề mặt màng tế bào lai, chứng tỏ các phân tử protein có khả năng di chuyển tự do trong mặt phẳng của lớp kép phospholipid; nếu protein bị cố định hoàn toàn tại những vị trí bất biến như trong mô hình giả định, hiện tượng trộn lẫn, phân bố lại này không thể xảy ra được; hơn nữa, tính linh động của protein màng còn cần thiết để giải thích nhiều hiện tượng sinh học khác, chẳng hạn khả năng các thụ thể màng tập trung lại tại một vị trí cụ thể trên màng khi cần thiết để khuếch đại tín hiệu, hay sự biến đổi hình dạng màng liên tục trong quá trình vận chuyển chất, xuất nhập bào; chính vì mô hình khảm động vừa giải thích được các bằng chứng thực nghiệm, vừa lí giải hợp lí nhiều hoạt động chức năng thiết yếu của màng sinh chất, nó được xem là mô hình mô tả chính xác, phù hợp hơn nhiều so với một cấu trúc màng cứng nhắc, cố định."
